-- v0.7.1 app schema (user_version 3); exported from the app database definition identical to tag v0.7.1.
CREATE TABLE "agents" ("id" TEXT NOT NULL, "scope" TEXT NOT NULL, "novel_id" TEXT NOT NULL DEFAULT '', "slug" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "prompt" TEXT NOT NULL, "category" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'chat', "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "use_custom_prompt" INTEGER NOT NULL DEFAULT 0 CHECK ("use_custom_prompt" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "allowed_tool_names" TEXT NOT NULL DEFAULT '[]', "ignored_skill_names" TEXT NOT NULL DEFAULT '[]', "provider_id" TEXT NULL, "model" TEXT NULL, "reasoning_effort" TEXT NULL, "avatar_path" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("scope", "novel_id", "slug", "deleted_at"));
CREATE TABLE "ai_chat_sessions" ("id" TEXT NOT NULL, "novel_id" TEXT NOT NULL, "parent_id" TEXT NULL, "title" TEXT NOT NULL DEFAULT '', "provider" TEXT NULL, "model" TEXT NULL, "mode" TEXT NOT NULL DEFAULT 'chat', "agent_slug" TEXT NULL, "reasoning_effort" TEXT NULL, "metadata" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "ai_providers" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "builtin" INTEGER NOT NULL DEFAULT 0 CHECK ("builtin" IN (0, 1)), "type" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("enabled" IN (0, 1)), "api_key" TEXT NOT NULL DEFAULT '', "base_url" TEXT NOT NULL DEFAULT '', "models" TEXT NOT NULL DEFAULT '[]', "image_models" TEXT NOT NULL DEFAULT '[]', "audio_models" TEXT NOT NULL DEFAULT '[]', "video_models" TEXT NOT NULL DEFAULT '[]', "embedding_models" TEXT NOT NULL DEFAULT '[]', "temperature" REAL NOT NULL DEFAULT 0.7, "max_turns" INTEGER NOT NULL DEFAULT 512, "reasoning_effort" TEXT NULL, "proxy_url" TEXT NOT NULL DEFAULT '', "proxy_username" TEXT NOT NULL DEFAULT '', "proxy_password" TEXT NOT NULL DEFAULT '', "access_key_id" TEXT NULL, "secret_access_key" TEXT NULL, "asset_project_name" TEXT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "ai_shortcut_actions" ("id" TEXT NOT NULL, "builtin_id" TEXT NULL, "name" TEXT NOT NULL, "prompt" TEXT NOT NULL, "locations" TEXT NOT NULL DEFAULT '[]', "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "auto_send" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_send" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("builtin_id", "deleted_at"));
CREATE TABLE "ai_usages" ("id" TEXT NOT NULL, "provider_id" TEXT NOT NULL, "model" TEXT NOT NULL, "session_id" TEXT NULL, "novel_id" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'chat', "run_id" TEXT NULL, "run_label" TEXT NULL, "input_tokens" INTEGER NOT NULL DEFAULT 0, "output_tokens" INTEGER NOT NULL DEFAULT 0, "cache_read_tokens" INTEGER NOT NULL DEFAULT 0, "cache_write_tokens" INTEGER NOT NULL DEFAULT 0, "reasoning_tokens" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "anonymous_outbox_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "event_id" TEXT NULL, "channel" TEXT NOT NULL, "priority" INTEGER NOT NULL, "endpoint" TEXT NOT NULL, "product_code" TEXT NOT NULL, "device_id" TEXT NOT NULL, "payload_json" TEXT NOT NULL, "occurred_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "next_retry_at" INTEGER NOT NULL, "attempt_count" INTEGER NOT NULL DEFAULT 0, UNIQUE ("event_id"));
CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL DEFAULT '', "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "app_states" ("key" TEXT NOT NULL, "value" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "assets" ("id" TEXT NOT NULL, "type" TEXT NOT NULL, "content" TEXT NULL, "name" TEXT NOT NULL DEFAULT '', "novel_id" TEXT NULL, "batch_id" TEXT NULL, "purpose" TEXT NOT NULL, "source" TEXT NOT NULL DEFAULT 'uploaded', "path" TEXT NULL, "sha256" TEXT NULL, "metadata_json" TEXT NULL, "favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("favorite" IN (0, 1)), "in_library" INTEGER NOT NULL DEFAULT 0 CHECK ("in_library" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "assistant_inbox" ("id" TEXT NOT NULL, "assistant_session_id" TEXT NOT NULL, "source" TEXT NOT NULL, "source_ref" TEXT NULL, "message_type" TEXT NOT NULL, "content" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "assistant_messages" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL, "role" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'text', "content" TEXT NOT NULL DEFAULT '', "blocks" TEXT NULL, "metadata" TEXT NULL, "input_tokens" INTEGER NOT NULL DEFAULT 0, "output_tokens" INTEGER NOT NULL DEFAULT 0, "cache_read_tokens" INTEGER NOT NULL DEFAULT 0, "cache_write_tokens" INTEGER NOT NULL DEFAULT 0, "reasoning_tokens" INTEGER NOT NULL DEFAULT 0, "sequence" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "assistant_sessions" ("id" TEXT NOT NULL, "chat_id" TEXT NOT NULL, "channel_type" TEXT NOT NULL, "provider" TEXT NULL, "model" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("channel_type", "chat_id"));
CREATE TABLE "custom_themes" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "base_theme" TEXT NOT NULL, "light_overrides" TEXT NOT NULL, "dark_overrides" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "feature_usages" ("feature_id" TEXT NOT NULL, "first_used_at" INTEGER NOT NULL, "last_used_at" INTEGER NOT NULL, "used_count" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("feature_id"));
CREATE TABLE "generation_tasks" ("kind" TEXT NOT NULL, "id" TEXT NOT NULL, "draft" INTEGER NOT NULL DEFAULT 0, "draft_task_id" TEXT NULL, "novel_id" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "result_asset_id" TEXT NULL, "provider_id" TEXT NOT NULL, "provider_type" TEXT NOT NULL, "model_id" TEXT NOT NULL, "provider_task_id" TEXT NULL, "polling_url" TEXT NULL, "output_url" TEXT NULL, "status" TEXT NOT NULL, "request_json" TEXT NOT NULL, "next_poll_at" INTEGER NULL, "error_code" TEXT NULL, "error_message" TEXT NULL, "error_detail" TEXT NULL, "path" TEXT NULL, "output_hash" TEXT NULL, "cancel_requested_at" INTEGER NULL, "submitted_at" INTEGER NULL, "completed_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "image_asset_references" ("id" TEXT NOT NULL, "asset_id" TEXT NOT NULL, "batch_id" TEXT NOT NULL, "reference_asset_id" TEXT NULL, "role" TEXT NOT NULL DEFAULT 'reference', "ordinal" INTEGER NOT NULL, "purpose" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "image_batch_slots" ("id" TEXT NOT NULL, "batch_id" TEXT NOT NULL, "ordinal" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "asset_id" TEXT NULL, "previous_asset_id" TEXT NULL, "error_code" TEXT NULL, "error_message" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "image_batches" ("id" TEXT NOT NULL, "novel_id" TEXT NULL, "purpose" TEXT NOT NULL DEFAULT 'cover', "status" TEXT NOT NULL DEFAULT 'pending', "prompt" TEXT NOT NULL, "params_json" TEXT NULL, "provider_id" TEXT NULL, "model" TEXT NULL, "requested_count" INTEGER NOT NULL DEFAULT 1, "completed_count" INTEGER NOT NULL DEFAULT 0, "error_message" TEXT NULL, "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "novel_agent_skill_blobs" ("sha256" TEXT NOT NULL, "content" TEXT NOT NULL, "byte_size" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("sha256"));
CREATE TABLE "novel_agent_skill_references" ("skill_id" TEXT NOT NULL REFERENCES novel_agent_skills (id) ON DELETE CASCADE, "path" TEXT NOT NULL, "content" TEXT NOT NULL, "byte_size" INTEGER NOT NULL, "sha256" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("skill_id", "path"));
CREATE TABLE "novel_agent_skill_revision_files" ("revision_id" TEXT NOT NULL REFERENCES novel_agent_skill_revisions (id) ON DELETE CASCADE, "path" TEXT NOT NULL, "sha256" TEXT NOT NULL, PRIMARY KEY ("revision_id", "path"));
CREATE TABLE "novel_agent_skill_revisions" ("id" TEXT NOT NULL, "skill_id" TEXT NOT NULL REFERENCES novel_agent_skills (id) ON DELETE CASCADE, "revision" INTEGER NOT NULL, "turn_id" TEXT NULL, "name" TEXT NOT NULL, "when_to_use" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL DEFAULT '', "prompt" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL DEFAULT '', "tags" TEXT NOT NULL DEFAULT '[]', "agent_scopes" TEXT NOT NULL DEFAULT '[]', "content_hash" TEXT NOT NULL, "change_source" TEXT NOT NULL, "change_note" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("skill_id", "revision"));
CREATE TABLE "novel_agent_skills" ("id" TEXT NOT NULL, "source_kind" TEXT NOT NULL, "source_listing_public_id" TEXT NULL, "source_version" TEXT NULL, "source_display_name" TEXT NULL, "name" TEXT NOT NULL, "when_to_use" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL, "prompt" TEXT NOT NULL, "agent_scopes" TEXT NOT NULL DEFAULT '[]', "category" TEXT NOT NULL DEFAULT '', "tags" TEXT NOT NULL DEFAULT '[]', "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "execution_blocked_reason" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("name"));
CREATE TABLE "novel_collection_members" ("collection_id" TEXT NOT NULL, "novel_id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("collection_id", "novel_id"));
CREATE TABLE "novel_collections" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "builtin" INTEGER NOT NULL DEFAULT 0, "filter_mode" TEXT NOT NULL DEFAULT 'manual', "filter" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "novels" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "author_name" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL, "cover_asset_id" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'in_progress', "type" TEXT NOT NULL DEFAULT 'original', "content_kind" TEXT NOT NULL DEFAULT 'novel', "source_novel_id" TEXT NULL, "content_database_path" TEXT NULL, "word_count" INTEGER NOT NULL DEFAULT 0, "draft" INTEGER NOT NULL DEFAULT 0 CHECK ("draft" IN (0, 1)), "category" TEXT NOT NULL DEFAULT '', "tags" TEXT NOT NULL DEFAULT '[]', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "plugin_permissions" ("plugin_id" TEXT NOT NULL, "permission" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("plugin_id", "permission"));
CREATE TABLE "plugin_registry" ("plugin_id" TEXT NOT NULL, "version" TEXT NOT NULL, "source" TEXT NOT NULL, "package_path" TEXT NOT NULL, "enabled" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("plugin_id"));
CREATE TABLE "plugin_secrets" ("plugin_id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("plugin_id", "key"));
CREATE TABLE "plugin_storage" ("plugin_id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("plugin_id", "key"));
CREATE TABLE "plugin_tasks" ("plugin_id" TEXT NOT NULL, "task_id" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1, "next_due_at" INTEGER NOT NULL, "run_id" TEXT NULL, "lease_expires_at" INTEGER NULL, "attempt" INTEGER NOT NULL DEFAULT 0, "last_started_at" INTEGER NULL, "last_finished_at" INTEGER NULL, "last_status" TEXT NOT NULL DEFAULT 'never', "last_summary" TEXT NULL, "last_error_code" TEXT NULL, "last_usage" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("plugin_id", "task_id"));
CREATE TABLE "production_styles" ("id" TEXT NOT NULL, "name" TEXT NOT NULL DEFAULT '', "before" TEXT NOT NULL DEFAULT '', "after" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "provider_assets" ("id" TEXT NOT NULL, "asset_id" TEXT NOT NULL, "provider_id" TEXT NOT NULL, "remote_id" TEXT NULL, "remote_task_id" TEXT NULL, "remote_group_id" TEXT NULL, "status" TEXT NOT NULL, "error_code" TEXT NULL, "error_message" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "reading_progress" ("novel_id" TEXT NOT NULL, "chapter_id" TEXT NULL, "scroll_offset" REAL NOT NULL DEFAULT 0.0, "last_read_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("novel_id"));
CREATE TABLE "session_subscriptions" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL, "subscriber_type" TEXT NOT NULL, "target_id" TEXT NOT NULL, "channel_type" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("session_id", "subscriber_type", "target_id"));
CREATE TABLE "todos" ("id" TEXT NOT NULL, "content" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "priority" TEXT NOT NULL DEFAULT 'medium', "session_id" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("session_id", "id"));
CREATE TABLE "tool_permission_rules" ("id" TEXT NOT NULL, "action" TEXT NOT NULL, "scope_type" TEXT NOT NULL, "work_id" TEXT NOT NULL, "scope_id" TEXT NOT NULL, "decision" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE INDEX ai_usages_by_created_at ON ai_usages (created_at);
CREATE INDEX ai_usages_by_session_id_created_at ON ai_usages (session_id, created_at);
CREATE INDEX ai_usages_by_source_created_at ON ai_usages (source, created_at);
CREATE INDEX anonymous_outbox_events_by_endpoint_product_code_device_id_next_retry_at_id ON anonymous_outbox_events (endpoint, product_code, device_id, next_retry_at, id);
CREATE INDEX anonymous_outbox_events_by_next_retry_at_priority_id ON anonymous_outbox_events (next_retry_at, priority, id);
CREATE INDEX assets_by_batch ON assets (batch_id);
CREATE INDEX assets_by_novel_purpose_deleted_created_id ON assets (novel_id, purpose, deleted_at, created_at, id);
CREATE INDEX assets_by_sha256 ON assets (sha256);
CREATE INDEX assets_by_type_novel_id_deleted_at_created_at ON assets (type, novel_id, deleted_at, created_at);
CREATE INDEX assistant_inbox_by_session_created ON assistant_inbox (assistant_session_id, created_at);
CREATE INDEX assistant_messages_by_session_created ON assistant_messages (session_id, created_at);
CREATE INDEX generation_tasks_by_draft_task_id_deleted_at ON generation_tasks (draft_task_id, deleted_at);
CREATE INDEX generation_tasks_by_kind_status_next_poll_at ON generation_tasks (kind, status, next_poll_at);
CREATE INDEX generation_tasks_by_novel_id_source_type_source_id_deleted_at ON generation_tasks (novel_id, source_type, source_id, deleted_at);
CREATE INDEX image_asset_references_by_asset_ordinal ON image_asset_references (asset_id, ordinal);
CREATE UNIQUE INDEX image_batch_slots_by_batch_id_ordinal_u ON image_batch_slots (batch_id, ordinal);
CREATE INDEX novel_agent_skill_revision_files_by_sha256 ON novel_agent_skill_revision_files (sha256);
CREATE INDEX novel_agent_skill_revisions_by_skill_id_created_at ON novel_agent_skill_revisions (skill_id, created_at);
CREATE INDEX novel_agent_skill_revisions_by_skill_id_turn_id ON novel_agent_skill_revisions (skill_id, turn_id);
CREATE UNIQUE INDEX novel_agent_skills_by_name_u ON novel_agent_skills (name);
CREATE INDEX novel_agent_skills_by_sort_order ON novel_agent_skills (sort_order);
CREATE INDEX novel_agent_skills_by_source_listing_public_id ON novel_agent_skills (source_listing_public_id);
CREATE INDEX novel_collection_members_by_novel_id ON novel_collection_members (novel_id);
CREATE INDEX novels_by_source_novel_id ON novels (source_novel_id);
CREATE UNIQUE INDEX novels_shelf_title_u
ON novels (title)
WHERE deleted_at = 0 AND draft = 0
;
CREATE INDEX plugin_tasks_by_enabled_next_due_at ON plugin_tasks(enabled, next_due_at);
CREATE INDEX provider_assets_by_asset_id_provider_id ON provider_assets (asset_id, provider_id);
CREATE INDEX provider_assets_by_status ON provider_assets (status);
CREATE UNIQUE INDEX tool_permission_rules_by_scope_type_work_id_scope_id_action_u ON tool_permission_rules(scope_type, work_id, scope_id, action);
PRAGMA user_version = 3;
